<span class="line"><span style="color:#6F42C1;">assert</span><span style="color:#24292E;">(Object.</span><span style="color:#6F42C1;">isExtensible</span><span style="color:#24292E;">(empty) </span><span style="color:#D73A49;">===</span><span style="color:#005CC5;"> true</span><span style="color:#24292E;">);</span></span>
